def transform(grid):
    H = len(grid)
    W = len(grid[0])

    def border(v):
        return (v in (1, 2, 3, 4, 5, 6, 7, 8, 9) and v != 0)

    for i in range(H):
        for j in range(W):
            v = grid[i][j]
            if not border(v):
                continue
            i2 = i + 1
            j2 = j + 1
            i3 = i + 2
            j3 = j + 2
            if i3 >= H or j3 >= W:
                continue
            if not (border(grid[i2][j2]) and border(grid[i2][j3]) and
                    border(grid[i3][j2]) and border(grid[i3][j3])):
                continue

            r1 = i2
            while r1 > 0 and border(grid[r1][j]):
                r1 -= 1
            c1 = j2
            while c1 > 0 and border(grid[i2][c1]):
                c1 -= 1

            r0 = r1 + 1
            c0 = c1 + 1

            r4 = i3
            while r4 + 1 < H and border(grid[r4 + 1][j]):
                r4 += 1
            c4 = j3
            while c4 + 1 < W and border(grid[i3][c4 + 1]):
                c4 += 1

            r3 = r4 - 1
            c3 = c4 - 1
            if r3 <= r1 or c3 <= c1:
                continue

            ok = True
            for rr in range(r2 := r3, r2 + 1):
                if grid[rr][c0] != v or grid[rr][c3] != v:
                    ok = False
            for cc in range(c2 := c1, c2 + 1):
                if grid[r0][cc] != v or grid[r3][cc] != v:
                    ok = False
            if not ok:
                continue

            vals = [v]
            for rr in range(r1, r3 + 1):
                for cc in range(c1, c3 + 1):
                    x = grid[rr][cc]
                    if x != v and x not in vals:
                        vals.append(x)

            fill = {}
            n = 0
            best = (10 ** 9, -1, -1, -1, -1)
            for p in range(1, 25):
                q = 0
                mism = 0
                known = 0
                last = None
                for rr in range(r1, r3 + 1):
                    for cc in range(c1, c3 + 1):
                        val = grid[rr][cc]
                        if val == v:
                            continue
                        t = ((rr - r1) * p + (cc - c1)) % (p * q) if q else 0
                        if last is not None and t == last[0] and val != last[1]:
                            mism += 1
                        last = (t, val)
                        if val not in vals:
                            known += 1
                if q > 0 and mism <= known and (mism, p, q) <= (best[0], best[1], best[2]):
                    best = (mism, p, q, r1, c1)
                    n = q

            if n <= 0:
                continue

            for rr in range(r1, r3 + 1):
                for cc in range(c1, c3 + 1):
                    t = (rr - r1) * best[1] + (cc - c1)
                    if t % best[2] == 0:
                        if grid[rr][cc] != v:
                            fill[(rr, cc)] = v

            for rr in range(r1, r3 + 1):
                for cc in range(c1, c3 + 1):
                    if (rr, cc) not in fill:
                        t = (rr - r1) * best[1] + (cc - c1)
                        val = None
                        for rr2 in range(r1, r3 + 1):
                            for cc2 in range(c1, c3 + 1):
                                if grid[rr2][cc2] != v and ((rr2 - r1) * best[1] + (cc2 - c1)) % best[2] == t % best[2]:
                                    val = grid[rr2][cc2]
                                    break
                            if val is not None:
                                break
                        if val is not None:
                            fill[(rr, cc)] = val

            if not fill:
                continue

            for (rr, cc), val in fill.items():
                grid[rr][cc] = val

    return grid
